<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
type Request=(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<any>;
const props=defineProps<{platform?:boolean;request:Request;readonly:boolean}>();
const data=ref<any>({models:[],providers:[],plans:[],usage:{},policy:{},plan:{}}),busy=ref(false),error=ref(''),notice=ref('');
const policy=reactive<any>({enabled:false,modelId:'',monthlyTokenLimit:500000,monthlyBudgetCents:0,maxInputChars:8000,maxOutputTokens:512,requestsPerMinute:5,expectedVersion:0});
const model=reactive<any>({id:null,provider:'OPENAI',model:'',inputPrice:'',outputPrice:'',maxOutputTokens:512,active:false,expectedVersion:0});
const budgetYuan=ref('0');
function money(c:number){return '¥'+((c||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function cents(v:string){const n=Number(v);if(!/^\d+(\.\d{1,2})?$/.test(v)||!Number.isFinite(n)||n<0)throw new Error('请输入最多两位小数的非负金额');return Math.round(n*100);}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
async function load(){data.value=await props.request(props.platform?'/platform/ai':'/ai/settings');if(props.platform)for(const p of data.value.plans)p.budgetYuan=(p.aiMonthlyBudgetCents/100).toFixed(2);if(!props.platform){Object.assign(policy,data.value.policy,{expectedVersion:data.value.policy.version,modelId:data.value.policy.modelId||''});budgetYuan.value=((policy.monthlyBudgetCents||0)/100).toFixed(2);}}
async function savePolicy(){await run(async()=>{await props.request('/ai/settings','PUT',{...policy,modelId:policy.modelId||null,monthlyBudgetCents:cents(budgetYuan.value)});await load();notice.value='企业 AI 设置已保存；每次发送仍需由使用人预览脱敏内容并确认。';});}
function edit(row:any){Object.assign(model,row,{expectedVersion:row.version,inputPrice:(row.inputPriceCentsPerMillion/100).toFixed(2),outputPrice:(row.outputPriceCentsPerMillion/100).toFixed(2)});}
function reset(){Object.assign(model,{id:null,provider:'OPENAI',model:'',inputPrice:'',outputPrice:'',maxOutputTokens:512,active:false,expectedVersion:0});}
async function saveModel(){await run(async()=>{await props.request('/platform/ai/models','POST',{id:model.id,provider:model.provider,model:model.model.trim(),inputPriceCentsPerMillion:cents(model.inputPrice),outputPriceCentsPerMillion:cents(model.outputPrice),maxOutputTokens:Number(model.maxOutputTokens),active:model.active,expectedVersion:model.expectedVersion});await load();reset();notice.value='模型配置已保存，未调用供应商接口。';});}
async function savePlan(row:any){await run(async()=>{await props.request('/platform/ai/plans/'+row.id,'PUT',{aiMonthlyTokenLimit:Number(row.aiMonthlyTokenLimit),aiMonthlyBudgetCents:cents(row.budgetYuan),expectedVersion:row.version});await load();notice.value='套餐预算上限已更新，企业设置仍需在上限内。';});}
onMounted(()=>run(load));
</script>
<template>
 <section class="ai-foundation">
  <div class="page-heading"><div><span class="eyebrow">AI OPERATIONS</span><h1>{{platform?'AI 模型与预算':'企业 AI 设置'}}</h1><p>{{platform?'配置可用模型和参考单价，控制套餐用量；服务端密钥不向客户展示。':'选择模型、设置预算并决定是否启用；业务记录继续按当前成员权限读取。'}}</p></div><button class="btn secondary" :disabled="busy" @click="run(load)">刷新</button></div>
  <div v-if="error" class="alert bad" role="alert">{{error}}</div><div v-if="notice" class="alert ok" role="status">{{notice}}</div>
  <template v-if="platform">
   <div class="cards"><article v-for="p in data.providers" :key="p.code" class="card"><span>{{p.code}}</span><strong>{{p.keyConfigured?'密钥已配置':'待配置密钥'}}</strong><small>{{p.serviceEnabled?'服务总开关已开启':'服务总开关关闭'}} · 仅配置模型不会外呼</small></article></div>
   <form class="card form" @submit.prevent="saveModel"><div class="title"><h2>{{model.id?'编辑模型':'新增模型'}}</h2><button v-if="model.id" class="text-button" type="button" @click="reset">取消编辑</button></div><div class="fields"><label>供应商<select v-model="model.provider"><option>OPENAI</option><option>DEEPSEEK</option><option>QWEN</option></select></label><label>模型标识<input v-model="model.model" maxlength="100" required placeholder="填写供应商提供的模型标识"/></label><label>输入参考单价（元 / 百万 Token）<input v-model="model.inputPrice" inputmode="decimal" required/></label><label>输出参考单价（元 / 百万 Token）<input v-model="model.outputPrice" inputmode="decimal" required/></label><label>单次输出上限<input v-model.number="model.maxOutputTokens" type="number" min="128" max="8192" required/></label><label class="check"><input v-model="model.active" type="checkbox"/>允许企业选择此模型</label></div><p class="hint">参考单价统一按人民币录入，需自行核对汇率及供应商报价。预算按保守预留值控制，不是供应商扣款账单。</p><button class="btn primary" :disabled="busy">保存模型配置</button></form>
   <section class="card table"><h2>模型清单</h2><div class="table-scroll"><table><thead><tr><th>供应商 / 模型</th><th>输入 / 输出参考单价</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in data.models" :key="row.id"><td>{{row.provider}}<small>{{row.model}}</small></td><td>{{money(row.inputPriceCentsPerMillion)}} / {{money(row.outputPriceCentsPerMillion)}}<small>每百万 Token</small></td><td>{{row.active?'可选':'停用'}} · {{row.keyConfigured?'连接参数就绪':'连接待配置'}}</td><td><button class="text-button" @click="edit(row)">编辑</button></td></tr><tr v-if="!data.models.length"><td colspan="4">尚未配置模型。先添加模型，再由产品方配置服务端密钥。</td></tr></tbody></table></div></section>
   <section class="card table"><h2>套餐 AI 预算上限</h2><div class="table-scroll"><table><thead><tr><th>套餐</th><th>每月 Token</th><th>每月参考费用（元）</th><th>操作</th></tr></thead><tbody><tr v-for="row in data.plans" :key="row.id"><td>{{row.name}}<small>调用额度 {{row.aiMonthlyRunLimit}}</small></td><td><input v-model.number="row.aiMonthlyTokenLimit" type="number" min="0" max="100000000" :aria-label="row.name+' Token 上限'"/></td><td><input v-model="row.budgetYuan" inputmode="decimal" :aria-label="row.name+' 费用上限'"/></td><td><button class="text-button" :disabled="busy" @click="savePlan(row)">保存上限</button></td></tr></tbody></table></div></section>
  </template>
  <template v-else>
   <div class="cards"><article class="card"><span>本月 Token</span><strong>{{data.usage.usedTokens||0}}</strong><small>预留 {{data.usage.reservedTokens||0}} · 按 UTC 自然月结算</small></article><article class="card"><span>本月参考费用</span><strong>{{money(data.usage.estimatedCostCents)}}</strong><small>预留 {{money(data.usage.reservedCostCents)}} · 人民币估算</small></article><article class="card"><span>连接状态</span><strong>{{data.masterEnabled?'总开关开启':'总开关关闭'}}</strong><small>{{data.models.length}} 个可选模型</small></article></div>
   <form class="card form" @submit.prevent="savePolicy"><h2>企业使用策略</h2><label class="check"><input v-model="policy.enabled" type="checkbox" :disabled="readonly||busy"/>启用本企业 AI</label><div class="fields"><label>模型<select v-model="policy.modelId" :disabled="readonly"><option value="">请选择模型</option><option v-for="m in data.models" :key="m.id" :value="m.id">{{m.provider}} / {{m.model}}{{m.keyConfigured?'':' · 连接待配置'}}</option></select></label><label>每月 Token 预算<input v-model.number="policy.monthlyTokenLimit" type="number" min="0" :max="data.plan.aiMonthlyTokenLimit||100000000" :disabled="readonly"/><small>套餐上限 {{data.plan.aiMonthlyTokenLimit||0}}</small></label><label>每月参考费用预算（元）<input v-model="budgetYuan" inputmode="decimal" :disabled="readonly"/><small>套餐上限 {{money(data.plan.aiMonthlyBudgetCents)}}</small></label><label>输入字符上限<input v-model.number="policy.maxInputChars" type="number" min="1000" max="20000" :disabled="readonly"/></label><label>单次输出 Token 上限<input v-model.number="policy.maxOutputTokens" type="number" min="128" max="8192" :disabled="readonly"/></label><label>每分钟请求上限<input v-model.number="policy.requestsPerMinute" type="number" min="1" max="60" :disabled="readonly"/></label></div><p class="hint">新企业默认关闭。用量在发送前原子预留；明确失败退回预留，超时或无法确认的供应商结果按预留值保守计入预算，不自动重试。预算为参考费用控制，实际金额以供应商账单为准。</p><button class="btn primary" :disabled="busy||readonly">保存企业 AI 设置</button></form>
   <section class="card form"><h2>发送与操作边界</h2><p>每次生成前展示实际脱敏内容、供应商及模型，确认在 5 分钟内有效且仅供同一次请求使用。资料、模型或企业策略变化后需要重新预览。</p><p>AI 仅生成摘要、建议和回复草稿。保存跟进、创建线索、审批、确认到账等操作继续由有权限的成员在业务模块办理。</p></section>
  </template>
 </section>
</template>
<style scoped>
.ai-foundation{display:flex;flex-direction:column;gap:20px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cards article{padding:22px;display:flex;flex-direction:column;gap:12px}.cards strong{font-size:24px}.cards span,.cards small,.hint,small{color:var(--text-muted,#92a8c3);font-size:12px;line-height:1.7}.form,.table{padding:24px}.form h2,.table h2{margin:0 0 18px;font-size:18px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:18px 0}.fields label{display:flex;flex-direction:column;gap:8px;font-size:13px}input,select{background:var(--input-bg,#15263d);border:1px solid var(--border-color,#354d6a);color:inherit;border-radius:8px;padding:11px;min-width:0;max-width:100%}.check{display:flex;align-items:center;gap:10px}.check input{width:auto}.table td{vertical-align:top}.table small{display:block;margin-top:7px}.form p{line-height:1.9}.hint{margin:18px 0}.title{display:flex;justify-content:space-between}.alert{border:1px solid var(--border-color,#354d6a);border-radius:8px;padding:14px}.bad{color:#fb9aa4}.ok{color:#6bdeb4}@media(max-width:800px){.cards,.fields{grid-template-columns:1fr}.form,.table{padding:18px}}
</style>
